package PCGEOS::Bootstrap;
use v5.20;
use strict;
use warnings;
use Exporter 'import';
use JSON::PP;
use Digest::SHA;
use File::Spec;
use File::Basename qw(dirname basename);
use File::Path qw(make_path remove_tree);
use File::Temp qw(tempfile tempdir);
use Cwd qw(abs_path getcwd);
use Config;
use IO::Uncompress::Gunzip;
use IO::Uncompress::RawInflate qw(rawinflate $RawInflateError);
use Compress::Raw::Zlib qw(crc32);
our @EXPORT_OK = qw(root read_json write_json read_bytes write_bytes sha256 progress safe_path verify_archive download extract_tar extract_zip apply_patch run_logged which assert_host install_atomic);
sub root { my $p=abs_path(__FILE__); return dirname(dirname(dirname(dirname($p)))); }
sub read_bytes { my($p)=@_; open my $h,'<:raw',$p or die "Cannot read $p: $!\n"; local $/; my $s=<$h>; close $h or die "$p: $!\n"; return defined($s)?$s:''; }
sub write_bytes { my($p,$s)=@_; make_path(dirname($p)); open my $h,'>:raw',$p or die "Cannot write $p: $!\n"; print {$h} $s or die "$p: $!\n"; close $h or die "$p: $!\n"; }
sub read_json { JSON::PP->new->utf8->decode(read_bytes($_[0])) }
sub write_json { write_bytes($_[0],JSON::PP->new->utf8->canonical->pretty->encode($_[1])); }
sub sha256 { open my $h,'<:raw',$_[0] or die "Cannot hash $_[0]: $!\n"; return Digest::SHA->new(256)->addfile($h)->hexdigest; }
sub progress { print STDERR $_[0],"\n"; }
sub which { my($n)=@_; return abs_path($n) if -f $n && -x $n; for my $d (File::Spec->path) { my $p=File::Spec->catfile($d,$n); return abs_path($p) if -f $p && -x $p; } return; }
sub assert_host { die "The tested compiler profile requires Linux x86-64; use WSL2 or an x86-64 Linux VM\n" unless $^O eq 'linux' && $Config{archname} =~ /(?:x86_64|amd64)/; }
sub safe_path { my($n)=@_; die "Unsafe source member name\n" if !defined($n)||$n eq ''||$n =~ /[\\:\0]/||$n =~ m{^/}; my @p=split m{/},$n,-1; die "Unsafe source member path\n" if grep { $_ eq ''||$_ eq '.'||$_ eq '..' } @p; return join '/',@p; }
sub _safe_target { my($dir,$name)=@_; safe_path($name); my $p=File::Spec->rel2abs($dir); my @dirs=File::Spec->splitdir($p); my $cur=File::Spec->rootdir; for my $part (@dirs,split m{/},$name) { next if $part eq ''; $cur=File::Spec->catfile($cur,$part); die "Refusing to extract through a symbolic link\n" if -l $cur; } return File::Spec->catfile($p,split m{/},$name); }
sub verify_archive { my($path,$lock)=@_; my $a=$lock->{archive}//$lock->{asset}; die "Archive differs from pinned size or SHA-256\n" unless -f $path && -s $path == $a->{bytes} && sha256($path) eq $a->{sha256}; }
sub download { my($path,$lock)=@_; my $a=$lock->{archive}//$lock->{asset}; make_path(dirname($path)); my @urls=grep {defined && length} ($a->{api_url},$a->{url}); my @errors; for my $url (@urls) { my $tmp="$path.part"; unlink $tmp; my @cmd=('curl','--fail','--location','--silent','--show-error','--connect-timeout','45','--max-time','600','--max-filesize',$a->{bytes},'--proto','=https','--proto-redir','=https','--user-agent','pcgeos1-sdk-bootstrap'); push @cmd,('-H','Accept: application/octet-stream','-H','X-GitHub-Api-Version: 2022-11-28') if defined($a->{api_url}) && $url eq $a->{api_url}; push @cmd,('-o',$tmp,$url); progress("Downloading pinned archive ($a->{bytes} bytes)"); my $ok=eval { system { $cmd[0] } @cmd; die "Download failed\n" if $?; verify_archive($tmp,$lock); rename($tmp,$path) or die "Cannot install download: $!\n"; 1 }; return if $ok; push @errors,$@; unlink $tmp; } die "Cannot obtain pinned archive: ".join('; ',@errors); }
sub _selected { my($n,$l)=@_; return 1 if grep {$_ eq $n} @{$l->{extract_files}//[]}; return scalar grep {index($n,$_)==0} @{$l->{extract_prefixes}//[]}; }
sub _take { my($h,$count)=@_; my $s=''; while(length($s)<$count) { my $n=read($h,my $b,($count-length($s)>1048576?1048576:$count-length($s))); die "Truncated archive\n" unless defined($n)&&$n; $s.=$b; } return $s; }
sub _skip { my($h,$n)=@_; while($n) { my $m=$n>1048576?1048576:$n; _take($h,$m); $n-=$m; } }
sub _tar_number { my($s)=@_; die "Unsupported tar numeric encoding\n" if ord(substr($s,0,1)) & 128; $s =~ s/[\0 ]+$//; $s =~ s/^ +//; die "Invalid tar number\n" if $s =~ /[^0-7]/; return oct($s||'0'); }
sub extract_tar {
 my($archive,$destination,$lock,$kind)=@_; make_path($destination); my($h,$pipe); if($kind eq 'xz') { open $h,'-|','xz','-dc','--',$archive or die "Cannot run xz: $!\n"; binmode $h; $pipe=1; } else { $h=IO::Uncompress::Gunzip->new($archive,MultiStream=>1) or die "Cannot open gzip archive: $IO::Uncompress::Gunzip::GunzipError\n"; }
 my($root,$longname); my %pax; my %seen;
 while(1) { my $header=_take($h,512); last if $header eq "\0"x512; my $stored=_tar_number(substr($header,148,8)); my $check=$header; substr($check,148,8)=' 'x8; my $sum=0; $sum += $_ for unpack 'C*',$check; die "Invalid tar header checksum\n" if $sum != $stored; my $name=unpack('Z100',substr($header,0,100)); my $prefix=unpack('Z155',substr($header,345,155)); $name="$prefix/$name" if length $prefix; my $size=_tar_number(substr($header,124,12)); my $type=substr($header,156,1); my $mode=_tar_number(substr($header,100,8)); my $pad=(512-$size%512)%512;
  if($type eq 'L'||$type eq 'x'||$type eq 'g') { die "Excessive tar extended metadata\n" if $size>1048576; my $d=_take($h,$size); _skip($h,$pad); if($type eq 'L') { $d =~ s/\0+$//; $longname=$d; } else { while(length $d) { die "Invalid pax record\n" unless $d =~ /\A(\d+) /; my $len=$1; die "Invalid pax length\n" if $len<3||$len>length($d); my $r=substr($d,0,$len,''); $r =~ /^\d+ ([^=]+)=(.*)\n\z/s or die "Invalid pax entry\n"; $pax{$1}=$2; } } next; }
  $name=delete($pax{path})//($longname//$name); undef $longname; $name =~ s{/$}{} if $type eq '5'; safe_path($name); my($first,$relative)=split m{/},$name,2; $root//=$first; die "Archive contains more than one source root\n" if $first ne $root; die "Unexpected source archive root\n" if $lock->{archive_root} && $first ne $lock->{archive_root};
  my $selected=defined($relative)&&length($relative)&&($kind eq 'xz'||_selected($relative,$lock)); if($selected&&$type ne '5') { die "Source links and special files are not accepted\n" unless $type eq '0'||$type eq "\0"; safe_path($relative); die "Duplicate source member: $relative\n" if $seen{$relative}++; my $dest=_safe_target($destination,$relative); make_path(dirname($dest)); my($out,$tmp)=tempfile('.extract-XXXXXX',DIR=>dirname($dest),UNLINK=>0); binmode $out; my $left=$size; while($left) { my $n=$left>1048576?1048576:$left; print {$out} _take($h,$n) or die "$tmp: $!\n"; $left-=$n; } close $out or die "$tmp: $!\n"; rename $tmp,$dest or die "$dest: $!\n"; chmod($mode & 0777,$dest) if $kind eq 'xz'; } else { _skip($h,$size); } _skip($h,$pad);
 }
 # Drain decompressor to validate its trailer and observe xz's exit status.
 while(read($h,my $rest,1048576)) {} close $h or die "Archive decompression failed\n";
}
sub extract_zip {
 my($archive,$destination,$lock)=@_; make_path($destination); open my $h,'<:raw',$archive or die "$archive: $!\n"; my $length=-s $h; my $tail_len=$length>65557?65557:$length; seek($h,$length-$tail_len,0) or die "ZIP seek failed\n"; my $tail=_take($h,$tail_len); my $eocd=rindex($tail,"PK\x05\x06"); die "Missing ZIP directory\n" if $eocd<0||length($tail)-$eocd<22; my($disk,$cd_disk,$n_disk,$n,$cd_size,$cd_offset,$comment)=unpack 'vvvvVVv',substr($tail,$eocd+4,18); die "Unsupported ZIP64 or multi-disk archive\n" if $disk||$cd_disk||$n_disk!=$n||$n==65535||$cd_offset==0xffffffff; die "Invalid ZIP comment\n" unless $eocd+22+$comment==length($tail); my $actual_cd=$length-$tail_len+$eocd-$cd_size; my $base=$actual_cd-$cd_offset; die "Invalid ZIP central directory\n" if $base<0; seek($h,$actual_cd,0) or die "ZIP seek failed\n"; my @records; my %seen;
 for(1..$n) { my $head=_take($h,46); die "Invalid ZIP directory entry\n" unless substr($head,0,4) eq "PK\x01\x02"; my($made,$need,$flags,$method,$mtime,$mdate,$crc,$packed,$size,$nl,$xl,$cl,$start_disk,$internal,$external,$offset)=unpack 'vvvvvvVVVvvvvvVV',substr($head,4); my $name=_take($h,$nl); _skip($h,$xl+$cl); next if $name =~ m{/$}||!_selected($name,$lock); safe_path($name); die "ZIP symbolic links are not accepted\n" if (($external>>16)&0170000)==0120000; die "Encrypted or split ZIP members unsupported\n" if $flags&1||$start_disk; die "Unsupported ZIP compression\n" unless $method==0||$method==8; die "Duplicate ZIP member\n" if $seen{$name}++; push @records,[$name,$method,$crc,$packed,$size,$base+$offset]; }
 my @entries; for my $r (@records) { my($name,$method,$crc,$packed,$size,$offset)=@$r; seek($h,$offset,0) or die "ZIP member seek failed\n"; my $local=_take($h,30); die "Invalid ZIP local header\n" unless substr($local,0,4) eq "PK\x03\x04"; my($nl,$xl)=unpack 'vv',substr($local,26,4); die "ZIP name collision\n" unless _take($h,$nl) eq $name; _skip($h,$xl); my $compressed=_take($h,$packed); my $data; if($method==0) { $data=$compressed; } else { rawinflate(\$compressed=>\$data,Transparent=>0) or die "Invalid ZIP deflate data: $RawInflateError\n"; } die "ZIP size/CRC mismatch\n" unless length($data)==$size && crc32($data)==$crc; my $dest=_safe_target($destination,$name); make_path(dirname($dest)); my($out,$tmp)=tempfile('.extract-XXXXXX',DIR=>dirname($dest),UNLINK=>0); binmode $out; print {$out} $data or die "$tmp: $!\n"; close $out or die "$tmp: $!\n"; rename $tmp,$dest or die "$dest: $!\n"; chmod 0755,$dest if $name =~ m{^binl64/[^/.]+$}; push @entries,$name; } close $h; my @missing=grep {!-f "$destination/$_"} @{$lock->{required_files}//[]}; die "Pinned archive lacks required files: ".join(', ',@missing)."\n" if @missing; return \@entries;
}
sub apply_patch { my($source,$lock,$sdkroot)=@_; $sdkroot//=root(); my $pp="$sdkroot/$lock->{patch}{file}"; die "Reviewed patch bundle differs from pinned SHA-256\n" unless sha256($pp) eq $lock->{patch}{sha256}; my $patch=read_json($pp); for my $r (@{$patch->{files}}) { my $p=_safe_target($source,safe_path($r->{path})); my $before=read_bytes($p); $before =~ s/\r\n/\n/g; die "Unexpected original source: $r->{path}\n" unless Digest::SHA::sha256_hex($before) eq $r->{before_sha256_lf}; my @lines=$before =~ /.*?(?:\r\n|[\n\r\x0b\x0c\x1c-\x1e\x85])|.+\z/gs; for my $e (reverse @{$r->{edits}}) { my($start,$count)=@$e{qw(start delete)}; die "Patch context mismatch: $r->{path}\n" unless ($count ? join('',@lines[$start..$start+$count-1]) : '') eq $e->{before}; my @after=$e->{after} =~ /.*?(?:\r\n|[\n\r\x0b\x0c\x1c-\x1e\x85])|.+\z/gs; splice @lines,$start,$count,@after; } my $after=join '',@lines; die "Patched source checksum mismatch: $r->{path}\n" unless Digest::SHA::sha256_hex($after) eq $r->{after_sha256_lf}; write_bytes($p,$after); } return $patch; }
sub run_logged { my($cmd,$env,$log,$cwd,$allow_fail)=@_; make_path(dirname($log)); $cwd//=dirname($log); my $pid=fork; die "Cannot fork: $!\n" unless defined $pid; if(!$pid) { chdir $cwd or die "$cwd: $!\n"; %ENV=%$env if $env; open STDOUT,'>:raw',$log or die "$log: $!\n"; open STDERR,'>&',\*STDOUT or die "$!\n"; exec {$cmd->[0]} @$cmd; die "Cannot execute $cmd->[0]: $!\n"; } waitpid($pid,0); my $status=$?; die "Command failed ($status); see $log\n" if $status&&!$allow_fail; return $status; }
sub install_atomic { my($prefix,$callback)=@_; $prefix=File::Spec->rel2abs($prefix); die "Refusing symlink installation prefix\n" if -l $prefix; make_path(dirname($prefix)); my $stage=tempdir('.sdk-install-XXXXXX',DIR=>dirname($prefix),CLEANUP=>0); my $result; my $ok=eval {$result=$callback->($stage); 1}; if(!$ok) { my $error=$@; remove_tree($stage); die $error; } my $backup="$prefix.previous-$$"; die "Existing installation backup: $backup\n" if -e $backup; if(-e $prefix) { rename($prefix,$backup) or die "Cannot preserve previous installation: $!\n"; } if(!rename($stage,$prefix)) { my $error=$!; rename($backup,$prefix) if -e $backup; remove_tree($stage); die "Cannot commit installation: $error\n"; } remove_tree($backup) if -e $backup; # Rewrite private-stage paths in metadata only after successful installation.
 my $replace; $replace=sub { my($v)=@_; if(ref($v) eq 'HASH') {return {map {$_=>$replace->($v->{$_})} keys %$v}} if(ref($v) eq 'ARRAY') {return [map {$replace->($_)} @$v]} if(!ref($v)&&defined($v)) {$v =~ s/\Q$stage\E/$prefix/g} return $v; }; $result=$replace->($result); return $result; }
1;
